/** Tool lifecycle order assigned by the driver; absent only in pre-v2 archives. */
startedOrder?: number;
completedOrder?: number | null;
/** Logical model response that chose the call; same-response calls cannot depend on each other's results. */
modelRequestIndex?: number;

if (!Array.isArray(value.servers) || value.servers.length > 8 || !value.servers.every(server => {
	if (!isRecord(server) || typeof server.name !== "string" || !/^[a-zA-Z0-9_.-]{1,64}$/.test(server.name) || Object.keys(server).some(key => !["name", "profile", "seed"].includes(key))) return false;
	if (["challenge-primary", "challenge-secondary"].includes(String(server.profile))) return Number.isSafeInteger(server.seed) && Number(server.seed) >= 1 && Number(server.seed) <= 65535;
	return ["primary", "secondary", "flaky"].includes(String(server.profile)) && server.seed === undefined;
}) || new Set(value.servers.map(server => server.name)).size !== value.servers.length) throw new Error("Invalid MCP servers");

const lifecycleOrders = new Set<number>();
for (const call of value.calls) {
	if (call.modelRequestIndex !== undefined && (!Number.isSafeInteger(call.modelRequestIndex) || call.modelRequestIndex < 1 || call.modelRequestIndex > Number(value.requests))) throw new Error("Invalid tool model-request identity");
	if (call.startedOrder === undefined && call.completedOrder === undefined) continue; // Historical evidence.
	if (!Number.isSafeInteger(call.startedOrder) || call.startedOrder < 1 || lifecycleOrders.has(call.startedOrder)) throw new Error("Invalid tool lifecycle order");
	lifecycleOrders.add(call.startedOrder);
	if (call.completedOrder !== null) {
		if (!Number.isSafeInteger(call.completedOrder) || call.completedOrder <= call.startedOrder || lifecycleOrders.has(call.completedOrder)) throw new Error("Invalid tool lifecycle order");
		lifecycleOrders.add(call.completedOrder);
	}
}

/** Absent in historical v1 runs; new runs always bind an explicit suite and fixture digest. */
suite?: AgentSuite;
