if (result.evaluation.suite === "mcp-challenge-v2") {
	summary.outcomes = { completed: 0, "honest-unavailable": 0, "wrong-source": 0, "unsupported-answer": 0, "incorrect-result": 0, "execution-error": 0 };
	for (const run of runs) {
		const outcome = run.error ? "execution-error" : run.grade && "outcome" in run.grade ? run.grade.outcome : "execution-error";
		summary.outcomes[outcome] += 1;
	}
}

export async function runAgentBenchmark(tasks: BenchmarkTask[], config: AgentRunConfig, outputPath: string): Promise<AgentBenchmarkResult> {
	tasks = structuredClone(tasks);
	const suite = parseAgentSuite(config.suite ?? (tasks.some(isChallengeTask) ? "mcp-challenge-v2" : "mcp-smoke-v1"));
	validateSuiteTasks(tasks, suite);

if (values.suite !== undefined && mode !== "agent") fail("Versioned agent suites require agent mode");
const suite = parseAgentSuite(values.suite);
const suiteTasks = tasksForSuite(suite);

if (request.dataset === "mcp-challenge-v2" && options.suite === undefined) throw new Error("v2 dataset requires explicit mcp.suite");
if (options.suite !== undefined) {
	if (mode !== "agent") throw new Error("Versioned suites require MCP agent mode");
	const suite = parseAgentSuite(options.suite);
	if (request.dataset !== undefined && request.dataset !== suite && !(suite === "mcp-smoke-v1" && request.dataset === "mcp-agent-v1")) throw new Error("Dataset conflicts with MCP suite");
	args.push("--suite", suite);
}
